350	func convertVisibilityFromStore(visibility store.Visibility) v1pb.Visibility {
351		switch visibility {
352		case store.Private:
353			return v1pb.Visibility_PRIVATE
354		case store.Protected:
355			return v1pb.Visibility_PROTECTED
356		case store.Public:
357			return v1pb.Visibility_PUBLIC
358		default:
359			return v1pb.Visibility_VISIBILITY_UNSPECIFIED
360		}
361	}
